package com.primehr.migration;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;class RrV45MigrationParityTest{@Test void pairedV45MigrationsHaveMatchingWorkflowStructures()throws Exception{String p=read("db/migration/postgresql/V45__rr_eligibility_evaluation_decision.sql").toLowerCase(),s=read("db/migration/sqlserver/V45__rr_eligibility_evaluation_decision.sql").toLowerCase();Set<String> names=Set.of("rr_evaluation_case","rr_eligibility_finding","rr_evaluator_assignment","rr_criterion_rating","rr_decision_event","rr_decision_issue","uk_rr_evaluation_nomination","uk_rr_eligibility_rule","uk_rr_evaluator_employee","uk_rr_rating_criterion","ix_rr_eval_status","ix_rr_assignment_case","ix_rr_decision_case");for(String m:Set.of(p,s)){assertThat(m).contains(names.toArray(String[]::new));assertThat(m).doesNotContain("insert into","delete from","drop table","payroll","employeeappointment");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
